using System.Buffers;
using System.Diagnostics;
using System.IO.Compression;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.ResponseCompression;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.ObjectPool;

var builder = WebApplication.CreateBuilder(args);

// ---- 缓存 ----
builder.Services.AddMemoryCache(options =>
{
    options.SizeLimit = 1024; // 限制缓存条目数
});
builder.Services.AddStackExchangeRedisCache(options =>
{
    options.Configuration = "localhost:6379";
    options.InstanceName = "demo_";
});

// ---- 响应压缩 ----
builder.Services.AddResponseCompression(options =>
{
    options.EnableForHttps = true;
    options.Providers.Add<BrotliCompressionProvider>();
    options.Providers.Add<GzipCompressionProvider>();
});
builder.Services.Configure<BrotliCompressionProviderOptions>(options =>
{
    options.Level = CompressionLevel.Fastest; // 动态内容用 Fastest
});

// ---- 对象池 ----
builder.Services.AddSingleton<ObjectPoolProvider, DefaultObjectPoolProvider>();

var app = builder.Build();
app.UseResponseCompression();

// ---- 性能监控中间件 ----
app.Use(async (context, next) =>
{
    var sw = Stopwatch.StartNew();
    await next(context);
    sw.Stop();
    context.Response.Headers["X-Response-Time"] = $"{sw.ElapsedMilliseconds}ms";
});

// ---- 内存缓存示例 ----
app.MapGet("/product/{id:int}", async (int id, IMemoryCache cache, IProductRepository repo) =>
{
    var cacheKey = $"product_{id}";
    var product = await cache.GetOrCreateAsync(cacheKey, async entry =>
    {
        entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10);
        entry.Size = 1;
        return await repo.GetByIdAsync(id);
    });
    return product is not null ? Results.Ok(product) : Results.NotFound();
});

// ---- 分布式缓存示例 ----
app.MapGet("/distributed/{key}", async (string key, IDistributedCache distCache) =>
{
    var cached = await distCache.GetStringAsync(key);
    if (cached is not null)
        return Results.Ok(JsonSerializer.Deserialize<CachedPayload>(cached));

    var payload = new CachedPayload(key, DateTime.UtcNow);
    await distCache.SetStringAsync(key, JsonSerializer.Serialize(payload),
        new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1)
        });
    return Results.Ok(payload);
});

// ---- ArrayPool 减少 LOH 分配 ----
app.MapGet("/process/{size:int}", (int size) =>
{
    var pool = ArrayPool<byte>.Shared;
    var buffer = pool.Rent(size);
    try
    {
        // 模拟处理
        for (int i = 0; i < size && i < buffer.Length; i++)
            buffer[i] = (byte)(i % 256);
        return Results.Ok(new { processed = size });
    }
    finally
    {
        pool.Return(buffer); // 归还到池，避免 GC
    }
});

// ---- ValueTask 高频缓存命中路径 ----
app.MapGet("/cached-or-db/{id:int}", async (int id, IMemoryCache cache) =>
{
    var result = await GetCachedOrDbAsync(cache, id);
    return Results.Ok(result);
});

app.Run();

// ---- ValueTask 示例方法 ----
static ValueTask<string> GetCachedOrDbAsync(IMemoryCache cache, int id)
{
    if (cache.TryGetValue($"v_{id}", out string? cached))
        return new ValueTask<string>(cached!); // 同步完成，零 Task 分配

    return new ValueTask<string>(LoadFromDbAsync(cache, id));
}

static async Task<string> LoadFromDbAsync(IMemoryCache cache, int id)
{
    await Task.Delay(10); // 模拟 DB
    var value = $"db_value_{id}";
    cache.Set($"v_{id}", value, TimeSpan.FromMinutes(5));
    return value;
}

// ---- 类型定义 ----
public record CachedPayload(string Key, DateTime CreatedAt);

public class Product { public int Id { get; set; } public string Name { get; set; } = ""; }

public interface IProductRepository
{
    Task<Product?> GetByIdAsync(int id);
}
